"""Interactive structural LOD comparison at whole, component and shell scales."""
import argparse,json
from pathlib import Path

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('out',type=Path);a=ap.parse_args();out=a.out.resolve();report=json.loads((out/'validation.json').read_bytes());rows=report['components'];images={};views=sorted({r['view'] for c in rows for r in c['views']},key=lambda s:(s!='e15-a60',s))
    for c in rows:
        group=c['id'].split('/')[0];images[group]={scope:{stage:{view:str(out/'review'/group/scope/(stage+'-'+view+'.png')) for view in views} for stage in ['before','after']} for scope in ['whole','component','shell']}
    table=''.join(f'<tr><td>{c["id"]}</td><td>{c["component_before"]:,}</td><td>{c["component_after"]:,}</td><td>{100*(1-c["component_after"]/c["component_before"]):.1f}%</td></tr>' for c in rows)
    page='''<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px var(--font-sans,system-ui);color:var(--foreground);line-height:1.45}h2{font-size:20px;margin:0 0 10px}p{color:var(--muted-foreground)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stats div{padding:16px;background:var(--secondary);border-radius:10px}.stats b{display:block;font-size:24px}.stats span{font-size:12px}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;margin:14px 0}td,th{padding:8px 4px;border-bottom:1px solid var(--border);text-align:right}td:first-child,th:first-child{text-align:left}select{margin:5px 8px 10px 0;padding:7px;color:var(--foreground);background:var(--secondary);border:1px solid var(--border);border-radius:7px}.images{display:grid;grid-template-columns:1fr 1fr;gap:8px}img{width:100%;border-radius:9px}figure{margin:0}figcaption,.note{font-size:12px;color:var(--muted-foreground)}@media(max-width:500px){table{font-size:11px}.stats div{padding:10px}.stats b{font-size:19px}}</style></head><body>
<h2>Dart frame & Outpost upper structure</h2><div class="stats"><div><b>SAVING</b><span>Placed triangles saved</span></div><div><b>FIELDTOTAL</b><span>Experimental field total</span></div><div><b>3 mm</b><span>Sampled visual ceiling</span></div></div>
<p>The prior whole-shell guard had retained almost all main-shell geometry. These candidates use the same 1 mm nominal / 3 mm sampled detail policy as the approved Base, starting from native source tessellation.</p>
<table><thead><tr><th>Component / placement</th><th>Approved</th><th>Candidate</th><th>Saved</th></tr></thead><tbody>TABLE</tbody></table>
<select id="group"><option value="dart-station">Dart station</option><option value="outpost">Outpost</option></select><select id="scope"><option value="whole">Complete source product</option><option value="component">Changed component</option><option value="shell">Changed structural shell</option></select><select id="view">VIEWS</select>
<div class="images"><figure><img id="before"><figcaption>Previously approved candidate</figcaption></figure><figure><img id="after"><figcaption>New structural LOD candidate</figcaption></figure></div><p id="metrics"></p>
<p class="note">All other shells, and chromatic/unresolved triangles in the changed shell, preserve exact exported positions, normals and materials. Source membership stays separate. No hole fills, parts removed, collision edits or runtime installation. Each scope has 18 matched source-pose flat diagnostic views; sampled distance is not a continuous surface guarantee.</p>
<p class="note">The selected Outpost adds a 3 mm colour-proximity protection band. Green masks match in every complete-product view. Some red occlusion differences remain, greatest in the top view (52 lost pixels); inspect top and underside angles too.</p>
<p class="note">Native discovery also found 270 small-bore candidates in the Dart frame and 197 in the Outpost upper shell. Those holes remain intact; they are follow-up candidates requiring local review.</p>
<script>const rows=ROWS,images=IMAGES;function update(){let group=document.querySelector('#group').value,scope=document.querySelector('#scope').value,view=document.querySelector('#view').value,row=rows.find(r=>r.id.startsWith(group+'/'));for(let stage of ['before','after'])document.querySelector('#'+stage).src=images[group][scope][stage][view];let metric=row.views.find(r=>r.scope===scope&&r.view===view);document.querySelector('#metrics').textContent=`Complete product: ${row.whole_before.toLocaleString()} → ${row.whole_after.toLocaleString()} triangles. Native sampled max: ${row.exported_native_sampled_deviation_mm.max.toFixed(3)} mm. This view's foreground difference: ${(100*metric.foreground_difference_relative_fraction).toFixed(3)}%.`;};document.querySelectorAll('select').forEach(s=>s.onchange=update);update();</script></body></html>'''
    page=page.replace('SAVING',f'{report["placed_triangle_saving"]:,}').replace('FIELDTOTAL',f'{report["candidate_field_placed_triangles"]/1e6:.3f}M').replace('TABLE',table).replace('VIEWS',''.join('<option>'+v+'</option>' for v in views)).replace('ROWS',json.dumps(rows)).replace('IMAGES',json.dumps(images));(out/'review.html').write_text(page)

if __name__=='__main__':main()
